import{_ as i,o as t,c as n,ah as r}from"./chunks/framework.Bja9t6Wf.js";const p=JSON.parse('{"title":"Teil 4: Die Witwe, die Politik und der Regen aus Gold","description":"","frontmatter":{},"headers":[],"relativePath":"oevp-spenden.md","filePath":"oevp-spenden.md"}'),a={name:"oevp-spenden.md"};function s(o,e,d,l,u,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="teil-4-die-witwe-die-politik-und-der-regen-aus-gold" tabindex="-1">Teil 4: Die Witwe, die Politik und der Regen aus Gold <a class="header-anchor" href="#teil-4-die-witwe-die-politik-und-der-regen-aus-gold" aria-label="Permalink to &quot;Teil 4: Die Witwe, die Politik und der Regen aus Gold&quot;">​</a></h1><p>In diesem Abschnitt unserer Mockumentary widmen wir uns der wohl modernsten und zugleich absurdesten Phase: Der Beziehung zwischen Heidi Horten und der österreichischen Volkspartei.</p><h2 id="die-kunst-der-stuckelung" tabindex="-1">Die Kunst der Stückelung <a class="header-anchor" href="#die-kunst-der-stuckelung" aria-label="Permalink to &quot;Die Kunst der Stückelung&quot;">​</a></h2><p>Unsere Recherche (unterstützt durch die fiktive Expertise von Dr. von Zitzewitz) zeigt ein faszinierendes Muster: Wenn man eine große Spende in sehr viele kleine Teile zerlegt, wird sie für das bloße Auge des Rechnungshofs quasi unsichtbar. Wir nennen das den &quot;Horten-Tarnkappen-Effekt&quot;.</p><h3 id="die-fakten-satirisch-aufbereitet" tabindex="-1">Die Fakten (satirisch aufbereitet): <a class="header-anchor" href="#die-fakten-satirisch-aufbereitet" aria-label="Permalink to &quot;Die Fakten (satirisch aufbereitet):&quot;">​</a></h3><ul><li><strong>Das Motiv:</strong> Pure Nächstenliebe zur politischen Landschaft.</li><li><strong>Die Methode:</strong> &quot;Pointillismus des Kapitals&quot; – viele kleine Punkte ergeben ein sehr großes Bild.</li><li><strong>Die Reaktion:</strong> Fassungslose Politiker, die beteuern, dass man &quot;kleine Aufmerksamkeiten&quot; ja wohl noch annehmen dürfe.</li></ul><h2 id="die-rechtfertigungs-arien" tabindex="-1">Die Rechtfertigungs-Arien <a class="header-anchor" href="#die-rechtfertigungs-arien" aria-label="Permalink to &quot;Die Rechtfertigungs-Arien&quot;">​</a></h2><p>Wir planen eine Montage von (geschauspielerten) Interviews mit ÖVP-Funktionären, die versuchen, die Spenden zu erklären.</p><blockquote><p><em>&quot;Frau Horten liebt einfach die Demokratie. Und Demokratie kostet eben... Porto. Sehr viel Porto.&quot;</em></p></blockquote><hr><p><em>Dieser Teil des Films wird besonders mutig mit den Grenzen zwischen Realität und Satire spielen.</em></p>',11)])])}const k=i(a,[["render",s]]);export{p as __pageData,k as default};
